long army::getAdjacentHex(long hex, long direction) const
{
    if (m_monInfo.m_attributes & 1) {
        if (m_facing == 0) {
            if (direction >= 3)
                hex--;
        } else if ((direction >= 0 && direction <= 2) || direction >= 6) {
            hex++;
        }
    }
    return getAdjacentCellIndex(hex, direction);
}

